from fastapi import FastAPIfrom .database import enginefrom . import modelsfrom .routes import auth_routes, search_routes, admin_routesfrom .config import settingsfrom fastapi.middleware.cors import CORSMiddlewaremodels.Base.metadata.create_all(bind=engine)app = FastAPI(title=settings.APP_NAME)app.add_middleware(    CORSMiddleware,    allow_origins=["*"],  # restringir em produção    allow_credentials=True,    allow_methods=["*"],    allow_headers=["*"],)app.include_router(auth_routes.router)app.include_router(search_routes.router)app.include_router(admin_routes.router)